  {700, 600}, {680, 668}, {635, 680}, {595, 678}, {560, 640},
  {550, 580}, {570, 530}, {610, 490}
}
local m_quince_protect = poly(pts_quince_mask):shrink(4)

local m_wall = m_above_table - m_jug_protect - m_quince_protect

